# bash completion for "__CB_NAME__" — generated by cmd-builder, do not edit.
__CB_FUNC__() {
  local IFS=$'\n' line cur prefix= wb
  local -a words out
  # We split the line ourselves: COMP_WORDS also splits on ":" and "="
  # (which would break e.g. "core:system").
  IFS=$' \t\n' read -ra words <<<"${COMP_LINE:0:COMP_POINT}"
  [[ ${COMP_LINE:0:COMP_POINT} == *[[:space:]] ]] && words+=('')
  cur=${words[${#words[@]}-1]}
  # Bash only replaces what follows the last ":" or "=": strip that prefix.
  wb=${COMP_WORDBREAKS//[^:=]/}
  [[ -n $wb ]] && prefix=${cur%"${cur##*[$wb]}"}
  out=($(__CB_NAME__ __complete -- "${words[@]:1}" 2>/dev/null))
  COMPREPLY=()
  for line in "${out[@]}"; do
    line=${line%%$'\t'*}
    COMPREPLY+=("${line#"$prefix"}")
  done
}
complete -o default -F __CB_FUNC__ __CB_NAME__
